	set idTypeNcid=idItem.idTypeNcid.ncid
	If (idTypeNcid="50450667"){
		If (idItem.idValue.content < MXPID){
			If (pcheckProviderPhysIndException=1){
				Set tSC1=target.SetValueAt("STF","MFI:MasterFileIdentifier.identifier","set","")
	  		}else{
				set pOrdPrvdr=1
				 Set tSC1=target.SetValueAt("PRA","MFI:MasterFileIdentifier.identifier","set","")
			}

		}
	}
	IF ($LF(cIdTypeNcids,idTypeNcid)>0){
		Set tSC1=target.SetValueAt(idItem.idValue.content,"MFEgrp("_(1)_").PRA:PractitionerIDNumbers("_(PraIndex)_").IDnumberST","set","")
		Set tSC1=target.SetValueAt(idTypeNcid,"MFEgrp("_(1)_").PRA:PractitionerIDNumbers("_(PraIndex)_").typeofIDnumberIS","set","")
		set PraIndex=PraIndex+1

	}
}
